<div class="account-pdf-shell"><div class="account-pdf-header"><a href="{{ route('file-master.show',$owner) }}" class="btn btn-light border"><i class="fas fa-arrow-left"></i></a><div><a href="{{ route('file-master.files.download',['owner'=>$owner,'fileName'=>$file->original_name]) }}" class="btn btn-light border mr-2"><i class="fas fa-download"></i></a><button id="zoomOut" class="btn btn-light border"><i class="fas fa-minus"></i></button><span id="zoomLabel" class="mx-2 font-weight-bold small">135%</span><button id="zoomIn" class="btn btn-light border"><i class="fas fa-plus"></i></button></div></div><div id="pdfBody" class="account-pdf-body"><div class="spinner-border text-primary mt-5"></div></div></div>
<script>document.addEventListener('DOMContentLoaded',async function(){const body=document.getElementById('pdfBody'),label=document.getElementById('zoomLabel');let pdf,scale=1.35;async function render(){body.innerHTML='';label.textContent=Math.round(scale*100)+'%';for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n),viewport=page.getViewport({scale});const canvas=document.createElement('canvas');canvas.className='account-pdf-page';canvas.width=viewport.width;canvas.height=viewport.height;body.appendChild(canvas);await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;}}try{pdf=await pdfjsLib.getDocument(@json(route('file-master.files.preview',['owner'=>$owner,'fileName'=>$file->original_name]))).promise;await render();}catch(e){body.innerHTML='<div class="alert alert-danger mt-5">PDF tidak dapat ditampilkan.</div>';}document.getElementById('zoomIn').onclick=async()=>{if(pdf&&scale<3){scale+=.2;await render()}};document.getElementById('zoomOut').onclick=async()=>{if(pdf&&scale>.6){scale-=.2;await render()}};});</script>
